mapper.sql:
FROM xsy_sales_order_item i
JOIN xsy_sales_order o ON o.id = i.order_id
WHERE o.customer_id = #{customerId}
  AND o.order_source = 'MALL'
  AND o.deleted = FALSE
  AND i.deleted = FALSE
  AND o.status IN ('PENDING', 'CONFIRMED')
AND o.created_at >= #{startAt}
AND o.created_at < #{endAt}
